// Logo.dev serves the real logo for a domain. Its publishable key is meant to be in the page. Without one,
// or when an image fails to load, the Simple Icons mark above (or the first letter) is shown instead.
const LOGO_DEV_TOKEN = import.meta.env.VITE_LOGO_DEV_TOKEN as string | undefined;

const DOMAINS: Record<string, string> = {
  Google: 'google.com',
  Facebook: 'facebook.com',
  Bing: 'bing.com',
  'Apple Maps': 'apple.com',
  Foursquare: 'foursquare.com',
  HERE: 'here.com',
  MapQuest: 'mapquest.com',
  TomTom: 'tomtom.com',
  Yelp: 'yelp.com',
  Tripadvisor: 'tripadvisor.com',
  Fonecta: 'fonecta.fi',
  WhatsApp: 'whatsapp.com',
  Messenger: 'messenger.com',
  Telegram: 'telegram.org',
  Signal: 'signal.org',
  Viber: 'viber.com',
};

/** Logo.dev image URL for a site, or undefined when there's no key or no known domain. */
export function logoUrl(name: string, size = 64) {
  const domain = DOMAINS[name];
  if (!LOGO_DEV_TOKEN || !domain) return undefined;
  return `https://img.logo.dev/${domain}?token=${LOGO_DEV_TOKEN}&size=${size}&format=png&retina=true`;
}

function Fallback(props: { name: string; box: string; svg: string }) {
  const icon = () => ICONS[props.name];
  return (
    <Show
      when={icon()}
      fallback={
        <span
          class={['grid shrink-0 place-items-center bg-base-200 font-bold text-base-content/70', props.box]}
          aria-hidden="true"
        >
          {props.name.charAt(0)}
        </span>
      }
    >
      {(i) => (
        <span
          class={['grid shrink-0 place-items-center', props.box]}
          style={{ background: `${i().color}14` }}
          aria-hidden="true"
        >
          <svg viewBox="0 0 24 24" class={props.svg} fill={i().color}>
            <path d={i().path} />
          </svg>
        </span>
      )}
    </Show>
  );
}

/** A site's logo on a small tile: the real one from Logo.dev, or a fallback. */
export function PublisherLogo(props: { name: string; size?: 'sm' | 'md' }) {
  const [failed, setFailed] = createSignal(false);
  const box = () => (props.size === 'sm' ? 'size-7 rounded-md' : 'size-10 rounded-field');
  return (
    <Show
      when={!failed() && logoUrl(props.name)}
      fallback={<Fallback name={props.name} box={box()} svg={props.size === 'sm' ? 'size-4' : 'size-5'} />}
    >
      {(src) => (
        <img
          src={src()}
          alt=""
          loading="lazy"
          class={['shrink-0 border border-base-300 bg-base-100 object-contain', box()]}
          onError={() => setFailed(true)}
        />
      )}
    </Show>
  );
}

/** Sites' logos in a row, each named on hover and for screen readers. */
export function LogoStrip(props: { sites: { name: string; logo: string }[] }) {
  return (
    <ul class="flex flex-wrap items-center gap-1.5">
      <For each={props.sites}>
        {(site) => (
          <li title={site.name}>
            <PublisherLogo name={site.logo} size="sm" />
            <span class="sr-only">{site.name}</span>
          </li>
        )}
      </For>
    </ul>
  );
}

/** Just the mark, for logo strips. Nothing is shown for a site with no logo at all. */
export function BrandMark(props: { name: string; class?: string }) {
  const [failed, setFailed] = createSignal(false);
  return (
    <Show
      when={!failed() && logoUrl(props.name)}
      fallback={
        <Show when={ICONS[props.name]}>
          {(i) => (
            <svg viewBox="0 0 24 24" class={props.class ?? 'size-6'} fill={i().color} aria-hidden="true">
              <path d={i().path} />
            </svg>
          )}
        </Show>
      }
    >
      {(src) => (
        <img
          src={src()}
          alt=""
          loading="lazy"
          class={['rounded-md object-contain', props.class ?? 'size-6']}
          onError={() => setFailed(true)}
        />
      )}
    </Show>
  );
}
